def f(n):
    def factorial(x):
        if x == 0:
            return 1
        result = 1
        for i in range(1, x + 1):
            result *= i
        return result

    def sum_range(start, end):
        return (end * (end + 1) // 2) - ((start - 1) * start // 2)

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_range(1, i))

    return result
